begin
  foreach v_table in array array['weekly_source_rule_sets','weekly_source_rule_set_versions','weekly_source_group_rule_assignments'] loop
    execute format('alter table public.%I enable row level security',v_table);

begin
  foreach v_name in array array['weekly_source_self_bill_reports','weekly_source_self_bill_report_line_bindings'] loop
    execute pg_catalog.format('alter table public.%I enable row level security',v_name);

begin
 foreach name in array array['weekly_source_pay_decisions','weekly_source_pay_decision_requests','weekly_source_pay_decision_preview_assemblies','weekly_source_pay_decision_preview_quotes','weekly_source_pay_decision_reviews','weekly_source_pay_decision_members','weekly_source_pay_decision_bindings','weekly_source_pay_decision_unprotect_preparations'] loop
  execute format('alter table private.%I enable row level security',name);

begin
  if to_regprocedure('private.weekly_source_agency_invoice_check_only_v1(uuid)') is not null then
    execute 'select private.weekly_source_agency_invoice_check_only_v1($1)' into v_agency using p_timesheet_id;

execute 'select count(*),jsonb_agg(to_jsonb(d))->0 from private.bpay_next_source_chosen_detail d
          where d.head_id=$1 and d.component_id=$2 and d.decision_bundle_id=$3 and d.bundle_revision=$4'
          into v_count,v_detail using h.id,(v_component->>'component_id')::uuid,h.decision_bundle_id,h.bundle_revision;

execute pg_catalog.format(
      'revoke all on table public.%I from public,anon,authenticated,service_role',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop policy if exists cloudtms_miget_service_owner_all on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'create policy cloudtms_miget_service_owner_all on public.%I for all to %I, service_role using (true) with check (true)',
      v_table.table_name,current_user
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_record_guard on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_fact_guard on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_truncate_guard on public.%I',
      v_table.table_name
    );

if v_table.record_class='IMMUTABLE_APPEND_ONLY' then
      execute pg_catalog.format(
        'create trigger weekly_source_immutable_record_guard before update or delete on public.%I for each row execute function private._weekly_source_immutable_record_guard_v1()',
        v_table.table_name
      );

execute pg_catalog.format(
        'create trigger weekly_source_immutable_fact_guard before update or delete on public.%I for each row execute function private._weekly_source_immutable_fact_guard_v1(%s)',
        v_table.table_name,v_lifecycle_columns
      );

if v_table.record_class in ('IMMUTABLE_APPEND_ONLY','IMMUTABLE_FACTS_WITH_LIFECYCLE') then
      execute pg_catalog.format(
        'create trigger weekly_source_immutable_truncate_guard before truncate on public.%I for each statement execute function private._weekly_source_immutable_record_guard_v1()',
        v_table.table_name
      );

if exists(select 1 from pg_catalog.pg_roles where rolname='authenticator') then
      execute pg_catalog.format(
        'revoke all on function %I.%I(%s) from authenticator',
        v_function.nspname,v_function.proname,v_function.identity_arguments
      );

if exists(select 1 from pg_catalog.pg_roles where rolname='supabase_admin') then
      execute pg_catalog.format(
        'revoke all on function %I.%I(%s) from supabase_admin',
        v_function.nspname,v_function.proname,v_function.identity_arguments
      );

for v_signature in
    select function_signature
    from private._weekly_source_acl_service_rpc_contract_v1()
  loop
    if pg_catalog.to_regprocedure(v_signature) is not null then
      execute 'grant execute on function '||v_signature||' to service_role';

execute pg_catalog.format(
      'revoke all on table public.%I from public,anon,authenticated,service_role',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop policy if exists cloudtms_miget_service_owner_all on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'create policy cloudtms_miget_service_owner_all on public.%I for all to %I, service_role using (true) with check (true)',
      v_table.table_name,current_user
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_record_guard on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_fact_guard on public.%I',
      v_table.table_name
    );

execute pg_catalog.format(
      'drop trigger if exists weekly_source_immutable_truncate_guard on public.%I',
      v_table.table_name
    );

if v_table.record_class='IMMUTABLE_APPEND_ONLY' then
      execute pg_catalog.format(
        'create trigger weekly_source_immutable_record_guard before update or delete on public.%I for each row execute function private._weekly_source_immutable_record_guard_v1()',
        v_table.table_name
      );

execute pg_catalog.format(
        'create trigger weekly_source_immutable_fact_guard before update or delete on public.%I for each row execute function private._weekly_source_immutable_fact_guard_v1(%s)',
        v_table.table_name,v_lifecycle_columns
      );

if v_table.record_class in ('IMMUTABLE_APPEND_ONLY','IMMUTABLE_FACTS_WITH_LIFECYCLE') then
      execute pg_catalog.format(
        'create trigger weekly_source_immutable_truncate_guard before truncate on public.%I for each statement execute function private._weekly_source_immutable_record_guard_v1()',
        v_table.table_name
      );

if exists(select 1 from pg_catalog.pg_roles where rolname='authenticator') then
      execute pg_catalog.format(
        'revoke all on function %I.%I(%s) from authenticator',
        v_function.nspname,v_function.proname,v_function.identity_arguments
      );

if exists(select 1 from pg_catalog.pg_roles where rolname='supabase_admin') then
      execute pg_catalog.format(
        'revoke all on function %I.%I(%s) from supabase_admin',
        v_function.nspname,v_function.proname,v_function.identity_arguments
      );

for v_signature in
    select function_signature
    from private._weekly_source_acl_service_rpc_contract_v1()
  loop
    if pg_catalog.to_regprocedure(v_signature) is not null then
      execute 'grant execute on function '||v_signature||' to service_role';

if (v_workflow.workflow_kind='CONTRACT_EXPENSE' and v_workflow.target_timesheet_id is null)
       or v_paper_source_move is not null then
      execute
        'select public.candidate_targetless_expense_paper_pack_enqueue_v1($1,$2,$3,$4,$5)'
        into v_paper_pack_result
        using v_environment,v_workflow.id,v_workflow.generation,
          p_idempotency_key||':paper-pack',p_now_utc;
